def word_frequency(text: str) -> dict[str, int]:
    words = text.lower().replace('.', '').replace(',', '').split()
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency
